# Generated by GitHub Copilot - Nov-06-2026
@pytest.mark.asyncio
async def test_laptop_upload_and_query(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    """Run real parsing, chunking, storage and API wiring with mocked model/search I/O."""
    for name, field in Settings.model_fields.items():
        monkeypatch.delenv(field.alias or name, raising=False)
        monkeypatch.delenv(name, raising=False)
    monkeypatch.setenv("CONFIG_YAML_PATH", str(ROOT / "config.yaml"))
    monkeypatch.setenv("LLM_PROVIDER", "ollama_chat")
    monkeypatch.setenv("LLM_MODEL", "qwen2.5:1.5b")
    monkeypatch.setenv("OPENAI_API_KEY", "")
    monkeypatch.setenv("UPLOADS_DIR", str(tmp_path / "uploads"))
    monkeypatch.setenv("LOGS_DIR", str(tmp_path / "logs"))

    embedding_model = Mock()
    embedding_model.get_sentence_embedding_dimension.return_value = 384
    embedding_model.encode.side_effect = lambda text, **kwargs: np.ones(
        384 if isinstance(text, str) else (len(text), 384)
    )
    monkeypatch.setattr(LocalEmbedder, "_ensure", lambda self: embedding_model)
    reranker_model = Mock()
    reranker_model.predict.return_value = np.array([0.9])
    monkeypatch.setattr(CrossEncoderReranker, "_ensure", lambda self: reranker_model)
    nli_model = Mock()
    nli_model.predict.return_value = np.array([[0.05, 0.9, 0.05]])
    monkeypatch.setattr(HallucinationCheckerGuardrail, "_ensure", lambda self: nli_model)

    client = Mock()
    client.indices.exists.return_value = False
    client.ping.return_value = True
    monkeypatch.setattr("app.main._opensearch_client", lambda settings: client)
    bulk = Mock(return_value=(1, []))
    monkeypatch.setattr("app.ingestion.indexers.helpers.bulk", bulk)
    provider = Mock()
    provider.acomplete = AsyncMock(return_value="The launch code is ORCHID [1].")
    monkeypatch.setattr("app.main.LLMFactory.create", lambda config, settings: provider)

    app = create_app()
    async with app.router.lifespan_context(app):
        state = app.state.app_state
        # Force cache off so the test does not depend on the user's local cache.backend setting.
        off = state.yaml_config.cache.model_copy(update={"backend": "none"})
        state.yaml_config = state.yaml_config.model_copy(update={"cache": off})
        state.semantic_cache._cfg = off
        state.redis = Mock(ping=AsyncMock(), scan_iter=Mock(), setex=AsyncMock())
        async with AsyncClient(
            transport=ASGITransport(app=app), base_url="http://test"
        ) as api:
            doc = Document()
            doc.add_paragraph("The launch code is ORCHID.")
            content = io.BytesIO()
            doc.save(content)
            upload = await api.post(
                "/documents/upload",
                files={"file": ("sample.docx", content.getvalue())},
            )
            assert upload.status_code == 200
            assert upload.json()["chunks"] == upload.json()["indexed"] == 1
            actions = bulk.call_args.args[1]
            source = actions[0]["_source"]
            assert len(source["embedding"]) == 384
            assert actions[0]["_index"] == "enterprise_rag_local_minilm_chunks"
            assert client.indices.create.call_args.kwargs["body"]["mappings"][
                "properties"
            ]["embedding"]["dimension"] == 384
            client.search.return_value = {
                "hits": {"hits": [{"_id": source["chunk_id"], "_score": 1.0, "_source": source}]}
            }
            documents = (await api.get("/documents")).json()["documents"]
            assert documents[0]["status"] == "ready"
            ready = (await api.get("/health/ready")).json()
            assert ready["ready"] is True
            assert ready["components"]["redis"] == {"enabled": False}
            answer = await api.post("/query", json={"query": "What is the launch code?"})
            assert answer.status_code == 200
            assert "ORCHID" in answer.json()["answer"]
            assert answer.json()["chunks_used"] == 1
            assert len(answer.json()["sources"]) == 1
            assert answer.json()["guardrail_warnings"] == []

            # Use the real LiteLLM streaming adapter with a mocked transport iterator.
            config = load_yaml_config(ROOT / "config.yaml")
            state.generation._llm = LiteLLMProvider(config.llm, state.settings)
            monkeypatch.setattr(
                "app.core.llm.litellm.acompletion",
                AsyncMock(return_value=_tokens()),
            )
            streamed = await api.post(
                "/query", json={"query": "What is the launch code?", "stream": True}
            )
            assert streamed.status_code == 200
            assert '"done": true' in streamed.text
            assert "ORCHID" in streamed.text
            state.redis.ping.assert_not_awaited()
            state.redis.scan_iter.assert_not_called()
            state.redis.setex.assert_not_awaited()
    client.close.assert_called_once()


# Generated by GitHub Copilot - Nov-06-2026
async def _tokens() -> AsyncIterator[Mock]:
    """Provide deterministic streaming transport chunks without contacting Ollama."""
    yield Mock(choices=[Mock(delta=Mock(content="The launch code is ORCHID [1]."))])
